CodeAssembler& CodeAssemblerFns9::vscatterqps(AsmMemoryOperand op0, AsmRegisterXmm op1) {
	Code code;
	if (register_ext::is_xmm(op0.index())) {
		code = Code::EVEX_Vscatterqps_vm64x_k1_xmm;
	} else if (register_ext::is_ymm(op0.index())) {
		code = Code::EVEX_Vscatterqps_vm64y_k1_xmm;
	} else {
		return set_error("vscatterqps: invalid operands");
	}
	return add_instr_with_state(Instruction::with2(code, to_memory_operand(op0), op1.register_()), op0.state());
}

