CodeAssembler& CodeAssemblerFns9::xsha1() {
	Code code;
	if (bitness() == 64) {
		code = Code::Xsha1_64;
	} else if (bitness() >= 32) {
		code = Code::Xsha1_32;
	} else {
		code = Code::Xsha1_16;
	}
	return add_instr(Instruction::with(code));
}

